const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const california = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'California'))
    .geometry();

  const mississippi = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'Mississippi'))
    .geometry();

  const startDate = '2005-07-12';
  const endDate = '2005-07-20';

  // 2. Data Acquisition
  const lstCollection = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterDate(startDate, endDate)
    .select('LST_Day_1km');

  const caCollection = lstCollection.filterBounds(california);
  const msCollection = lstCollection.filterBounds(mississippi);

  const caSize = caCollection.size().getInfo();
  const msSize = msCollection.size().getInfo();

  console.log(`California images: ${caSize}`);
  console.log(`Mississippi images: ${msSize}`);

  if (caSize === 0 || msSize === 0) {
    console.log("No data found for one or both states.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create mean composites
  const caMean = caCollection.mean();
  const msMean = msCollection.mean();

  // Convert from Kelvin*50 to Celsius
  const caLST = caMean.multiply(0.02).subtract(273.15);
  const msLST = msMean.multiply(0.02).subtract(273.15);

  // 4. Calculate mean temperatures with pixel count
  const caStats = caLST.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: california,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const msStats = msLST.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: mississippi,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const caTempMean = caStats.LST_Day_1km_mean;
  const caTempCount = caStats.LST_Day_1km_count;
  const msTempMean = msStats.LST_Day_1km_mean;
  const msTempCount = msStats.LST_Day_1km_count;

  console.log(`CA: Temp=${caTempMean}°C, Pixels=${caTempCount}`);
  console.log(`MS: Temp=${msTempMean}°C, Pixels=${msTempCount}`);

  // 5. Validation & Final Answer
  if (caTempCount === 0 || msTempCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (caTempMean === null || msTempMean === null || 
      isNaN(caTempMean) || isNaN(msTempMean) ||
      caTempMean < -50 || caTempMean > 70 ||
      msTempMean < -50 || msTempMean > 70) {
    console.log("Invalid temperature calculation.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (caTempMean > msTempMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
